#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-09

# scripts/bump-stable-pin.sh
#
# Advance the PINNED stable marketplace channel to a GA release: move its
# `version` and its `source.ref` in the SAME write, so they can never disagree.
#
# WHY THIS EXISTS
# ---------------
# Since the channel split (#3340) `.claude-plugin/marketplace.json` carries two
# entries: `ork` pinned to the last stable tag, and `ork-alpha` tracking main.
# Three things write that file today and NONE of them moves the pin:
#
#   .release-please-config.json  ->  $.plugins[1].version   (alpha only, by index)
#   scripts/stamp-counts.sh      ->  the entry whose source.ref == "main"
#   scripts/stamp-counts.sh      ->  descriptions
#
# So on a GA release the pin stayed at the PREVIOUS tag until someone edited it
# by hand. tests/schemas/test-alpha-channel.sh turns a half-bump red, but a
# guard is not a writer. This is the writer (#3350).
#
# WHY IT IS NOT FOLDED INTO stamp-counts.sh
# -----------------------------------------
# stamp-counts.sh runs on every build, and its own comment block records the
# incident where doing exactly that clobbered the pinned entry from a release
# branch checkout. Moving the pin is a RELEASE event, not a build event, so it
# is driven from the tag-triggered workflow (.github/workflows/release.yml).
#
# WHY THE ENTRY IS NOT ADDRESSED BY INDEX
# ---------------------------------------
# Same reason stamp-counts.sh stopped using `.plugins[0]`: array position is not
# identity. Reordering the entries would silently redirect the write onto the
# tracking channel. The pinned entry is selected by what makes it pinned — a
# source.ref that is a real ref rather than a moving branch.
#
# Usage:
#   scripts/bump-stable-pin.sh <version> [marketplace.json]
#
# Exit codes (the caller branches on these, not on stdout):
#   0  pin moved, file rewritten
#   3  nothing to do — prerelease version, or the pin is already there
#   1  refused — unusable version, missing file, or no single pinned entry

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=scripts/lib/semver.sh
. "$SCRIPT_DIR/lib/semver.sh"

VERSION="${1:-}"
MARKETPLACE="${2:-$SCRIPT_DIR/../.claude-plugin/marketplace.json}"

if [[ -z "$VERSION" ]]; then
    echo "bump-stable-pin: usage: $0 <version> [marketplace.json]" >&2
    exit 1
fi

if [[ ! -f "$MARKETPLACE" ]]; then
    echo "bump-stable-pin: no such file: $MARKETPLACE" >&2
    exit 1
fi

# A prerelease must NEVER move the stable pin. That is the entire channel
# design: 10.0.0-alpha.N ships through ork-alpha while ork stays on the last GA
# tag. Checked before the shape test below so the no-op reads as a no-op rather
# than as a malformed version.
if semver_is_prerelease "$VERSION"; then
    echo "bump-stable-pin: $VERSION is a prerelease — stable pin left untouched."
    exit 3
fi

# Fail closed on anything that is not a plain GA core version. The value lands
# in a git ref and in a file CC validates at plugin load; garbage in either is a
# broken install for every stable user.
if [[ ! "$VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
    echo "bump-stable-pin: '$VERSION' is not a GA semver core version (X.Y.Z)." >&2
    exit 1
fi

# "Pinned" means: has a source.ref, and that ref is not a moving branch. Same
# definition tests/schemas/test-alpha-channel.sh uses to judge the stable entry.
#
# The filter is spelled out literally in the jq program rather than passed
# through a shell variable. tests/security/test-jq-injection.sh rejects any
# shell interpolation into a jq PROGRAM, and it is right to: the program is
# code, so a variable there is the same shape as an eval. Selecting once into
# PINNED_JSON keeps the filter defined in exactly one place without putting a
# shell variable inside the program text.
PINNED_JSON=$(jq -c '
  [.plugins[] | select((.source.ref // "") | (. != "" and . != "main" and . != "HEAD"))]
' "$MARKETPLACE")

pinned_count=$(printf '%s' "$PINNED_JSON" | jq 'length')
if [[ "$pinned_count" != "1" ]]; then
    echo "bump-stable-pin: expected exactly 1 pinned entry, found $pinned_count — refusing to guess." >&2
    exit 1
fi

cur_ref=$(printf '%s' "$PINNED_JSON" | jq -r '.[0].source.ref')
cur_ver=$(printf '%s' "$PINNED_JSON" | jq -r '.[0].version // ""')

if [[ "$cur_ref" == "v$VERSION" && "$cur_ver" == "$VERSION" ]]; then
    echo "bump-stable-pin: pin is already at v$VERSION — nothing to do."
    exit 3
fi

# Both fields in ONE jq program. Two sequential writes is how they end up
# disagreeing when the second one fails.
#
# --arg, never interpolation into the program text: a version is data. The same
# rule is enforced on the test side (tests/schemas/test-alpha-channel.sh:77).
tmp="${MARKETPLACE}.tmp"
jq --arg v "$VERSION" '
  (.plugins[] | select((.source.ref // "") | (. != "" and . != "main" and . != "HEAD")))
  |= (.version = $v | .source.ref = "v" + $v)
' "$MARKETPLACE" > "$tmp"
mv "$tmp" "$MARKETPLACE"

echo "bump-stable-pin: stable pin ${cur_ver} @ ${cur_ref} -> ${VERSION} @ v${VERSION}"
